const languageButton = document.querySelector('.language-switch');
const menuButton = document.querySelector('.menu-toggle');
const mobileNav = document.querySelector('#mobile-nav');
let language = 'en';

function setMenu(open) {
  mobileNav.hidden = !open;
  menuButton.setAttribute('aria-expanded', String(open));
  menuButton.setAttribute('aria-label', copy[language][open ? 'closeMenu' : 'menu']);
}

function setLanguage(next) {
  language = next === 'ar' ? 'ar' : 'en';
  const text = copy[language];
  document.documentElement.lang = language;
  document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
  document.querySelectorAll('[data-i18n]').forEach(node => { node.textContent = text[node.dataset.i18n]; });
  document.querySelectorAll('[data-alt]').forEach(node => { node.alt = text[node.dataset.alt]; });
  document.querySelectorAll('[data-label]').forEach(node => { node.setAttribute('aria-label', text[node.dataset.label]); });
  document.querySelectorAll('[data-whatsapp]').forEach(node => {
    const service = node.dataset.whatsapp;
    const message = service === 'general' ? text.messages.general : text.messages.service.replace('{service}', text[service]);
    node.href = 'https://wa.me/96170576915?text=' + encodeURIComponent(message);
  });
  languageButton.textContent = language === 'en' ? 'العربية' : 'EN';
  languageButton.lang = language === 'en' ? 'ar' : 'en';
  document.title = text.title;
  document.querySelector('meta[name="description"]').content = text.description;
  setMenu(false);
  // Storage can be unavailable in privacy modes; the language switch still works.
  try { localStorage.setItem('barberous-language', language); } catch {}
}

languageButton.addEventListener('click', () => setLanguage(language === 'en' ? 'ar' : 'en'));
menuButton.addEventListener('click', () => setMenu(mobileNav.hidden));
mobileNav.querySelectorAll('a').forEach(link => link.addEventListener('click', () => setMenu(false)));
document.addEventListener('keydown', event => {
  if (event.key === 'Escape' && !mobileNav.hidden) { setMenu(false); menuButton.focus(); }
});
window.matchMedia('(min-width: 761px)').addEventListener('change', event => { if (event.matches) setMenu(false); });
document.querySelector('#year').textContent = new Date().getFullYear();
let savedLanguage;
try { savedLanguage = localStorage.getItem('barberous-language'); } catch {}
setLanguage(savedLanguage === 'ar' ? 'ar' : 'en');
